const DAY = 86_400_000

export function formatLocalTime(timestamp, format = "relative", now = new Date()) {
  const date = new Date(timestamp)
  if (Number.isNaN(date.getTime())) return ""

  switch (format) {
    case "time": return new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" }).format(date)
    case "long": return new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric", hour: "numeric", minute: "2-digit" }).format(date)
    case "day": return new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" }).format(date)
    case "date": return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" }).format(date)
    case "numeric": return new Intl.DateTimeFormat("en-US", { month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit" }).format(date)
    case "short": return shortDate(date, now)
    default: return relativeDate(date, now)
  }
}

function shortDate(date, now) {
  return new Intl.DateTimeFormat("en-US", {
    month: "short", day: "numeric", ...(date.getFullYear() !== now.getFullYear() ? { year: "numeric" } : {})
  }).format(date)
}

function relativeDate(date, now) {
  // Compare local calendar days, not elapsed 24-hour periods (DST and midnight matter).
  const days = Math.round((Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) -
    Date.UTC(now.getFullYear(), now.getMonth(), now.getDate())) / DAY)

  if (days === 0) return formatLocalTime(date, "time", now)
  if (days === -1) return "yesterday"
  if (days === 1) return "tomorrow"
  if (days < 0 && days >= -6) return `${-days} days ago`
  if (days > 1 && days <= 6) return `in ${days} days`
  return shortDate(date, now)
}
EOF
