import { Controller } from "@hotwired/stimulus"
import { formatLocalTime } from "helpers/local_time"

const REFRESH_INTERVAL = 60_000

export default class extends Controller {
  static values = { format: String }

  connect() {
    this.update()
    this.timer = setInterval(() => this.update(), REFRESH_INTERVAL)
  }

  disconnect() {
    clearInterval(this.timer)
  }

  update() {
    const date = this.element.dateTime
    this.element.textContent = formatLocalTime(date, this.formatValue)
    this.element.title = new Date(date).toLocaleString("en-US", { dateStyle: "full", timeStyle: "short" })
  }
}
